// Generated by scripts/sync-hosting.js; edit the root market.js.
export const { Market, ROUND_MS, floorShares } = (() => {
"use strict";
  const ROUND_MS = 300000;
  const EPS = 0.0000001;
  const round = (n) => Math.round(n * 1e8) / 1e8;
  const floorShares = (n) => Math.floor((n + 1e-9) * 10000) / 10000;
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const emptyPosition = () => ({ shares: 0, cost: 0 });
  function random(seed) {
    return function () {
      seed |= 0;
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  class Market {
    constructor(options = {}) {
      this.clock = options.now || Date.now;
      this.liquidity = options.liquidity !== false;
      this.botsEnabled = options.bots !== false && this.liquidity;
      this.state = options.state || {
        version: 1,
        seed: options.seed || Math.floor(Math.random() * 2147483647),
        seq: 0,
        players: {},
        orders: [],
        trades: [],
        history: [],
        round: null,
      };
      if (this.state.version !== 1)
        throw new Error("Unsupported saved market version.");
      if (!this.state.round)
        this.newRound(Math.floor(this.clock() / ROUND_MS) * ROUND_MS, 97426.5);
      this.advance();
    }

    id(prefix) {
      return `${prefix}-${++this.state.seq}`;
    }

    newRound(start, opening) {
      const rng = random(this.state.seed ^ Math.floor(start / ROUND_MS));
      const path = [opening];
      let velocity = 0;
      const drift = (rng() - 0.5) * 0.48;
      for (let i = 1; i <= 300; i++) {
        const noise = (rng() + rng() + rng() - 1.5) * 7;
        velocity = velocity * 0.32 + noise + drift;
        path.push(
          Math.round(Math.max(1000, path[i - 1] + velocity) * 100) / 100,
        );
      }
      this.state.round = {
        id: String(start),
        start,
        end: start + ROUND_MS,
        opening,
        path,
        volume: 0,
        lastTick: -1,
        liquidityUsed: {},
        inventory: { up: 0, down: 0 },
        botTick: -1,
      };
      this.state.trades = [];
      if (this.botsEnabled) this.seedBots();
    }

    addPlayer(id) {
      if (!/^[a-zA-Z0-9_-]{8,80}$/.test(id))
        throw new Error("Invalid guest session.");
      if (!Object.hasOwn(this.state.players, id)) {
        let guestNumber =
          Object.values(this.state.players).filter((p) => !p.bot).length + 1;
        while (
          Object.values(this.state.players).some(
            (p) => p.name.toLowerCase() === `guest ${guestNumber}`,
          )
        )
          guestNumber++;
        this.state.players[id] = {
          id,
          name: `Guest ${guestNumber}`,
          balance: 1000,
          positions: { up: emptyPosition(), down: emptyPosition() },
          history: [],
          realized: 0,
          joinedAt: this.clock(),
        };
      }
      return this.state.players[id];
    }

    updateProfile(id, input) {
      const player = this.player(id);
      const name = typeof input.name === "string" ? input.name.trim() : "";
      const bio = typeof input.bio === "string" ? input.bio.trim() : "";
      if (!/^[a-zA-Z0-9][a-zA-Z0-9_. -]{2,23}$/.test(name))
        throw new Error(
          "Use 3–24 letters, numbers, spaces, dots, underscores, or hyphens.",
        );
      if (bio.length > 200) throw new Error("Keep your bio to 200 characters.");
      if (
        !Number.isInteger(input.avatar) ||
        input.avatar < 0 ||
        input.avatar > 7
      )
        throw new Error("Choose one of the profile pictures.");
      if (
        Object.values(this.state.players).some(
          (p) => p.id !== id && p.name.toLowerCase() === name.toLowerCase(),
        )
      )
        throw new Error("That username is already taken. Try another.");
      player.name = name;
      player.bio = bio;
      player.avatar = input.avatar;
    }

    recordActivity(player, entry) {
      if (player.bot) return;
      player.activity ||= [];
      player.activity.unshift({
        id: this.id("activity"),
        time: this.clock(),
        roundId: this.state.round.id,
        ...entry,
      });
      player.activity = player.activity.slice(0, 500);
      if (entry.type === "buy" || entry.type === "sell") {
        player.totalVolume = round((player.totalVolume || 0) + entry.total);
        if (player.lastTradedRound !== this.state.round.id) {
          player.marketsTraded = (player.marketsTraded || 0) + 1;
          player.lastTradedRound = this.state.round.id;
        }
      }
      if (entry.profit > (player.biggestWin || 0))
        player.biggestWin = entry.profit;
    }

    player(id) {
      const player = this.state.players[id];
      if (!player)
        throw new Error("Guest session not found. Refresh to reconnect.");
      return player;
    }

    price(now = this.clock()) {
      return this.state.round.path[
        clamp(Math.floor((now - this.state.round.start) / 1000), 0, 300)
      ];
    }

    probability(now = this.clock()) {
      const r = this.state.round;
      const seconds = Math.max(1, (r.end - now) / 1000);
      const z = (this.price(now) - r.opening) / (4.1 * Math.sqrt(seconds));
      return clamp(
        Math.round(100 / (1 + Math.exp(-1.65 * z))) / 100,
        0.02,
        0.98,
      );
    }

    quotes(side, now = this.clock()) {
      const inventory = this.state.round.inventory || { up: 0, down: 0 };
      const skew = clamp(
        (inventory.down - inventory.up) * 0.00001,
        -0.02,
        0.02,
      );
      const upMid = clamp(
        Math.round((this.probability(now) + skew) * 100) / 100,
        0.02,
        0.98,
      );
      const mid = side === "up" ? upMid : 1 - upMid;
      return {
        bid: round(clamp(mid - 0.01, 0.01, 0.98)),
        ask: round(clamp(mid + 0.01, 0.02, 0.99)),
      };
    }

    availableShares(id, side) {
      return round(
        this.player(id).positions[side].shares -
          this.state.orders
            .filter(
              (o) =>
                o.playerId === id && o.side === side && o.action === "sell",
            )
            .reduce((sum, o) => sum + o.remaining, 0),
      );
    }

    offers(side, action, excludeId, now = this.clock()) {
      const offers = this.state.orders
        .filter(
          (o) =>
            o.side === side &&
            o.action !== action &&
            o.playerId !== excludeId &&
            o.remaining > EPS,
        )
        .map((o) => ({
          id: o.id,
          price: o.price,
          quantity: o.remaining,
          source: "player",
          order: o,
          created: o.created,
        }));
      if (this.liquidity) {
        const q = this.quotes(side, now);
        for (let i = 0; i < 6; i++) {
          const price = round(
            clamp(
              (action === "buy" ? q.ask : q.bid) +
                (action === "buy" ? i : -i) * 0.01,
              0.01,
              0.99,
            ),
          );
          const key = `${side}:${action}:${price}`;
          if (offers.some((o) => o.source === "simulation" && o.id === key))
            continue;
          const rng = random(
            this.state.seed +
              Math.floor(now / 1000) * 31 +
              i * 17 +
              (side === "up" ? 0 : 51) +
              (action === "buy" ? 73 : 0),
          );
          const capacity = Math.floor(80 + rng() * 170 + i * 110);
          const quantity = round(
            Math.max(0, capacity - (this.state.round.liquidityUsed[key] || 0)),
          );
          if (quantity > EPS)
            offers.push({
              id: key,
              price,
              quantity,
              source: "simulation",
              created: 0,
            });
        }
      }
      return offers.sort(
        (a, b) =>
          (action === "buy" ? a.price - b.price : b.price - a.price) ||
          a.created - b.created,
      );
    }

    creditShares(player, side, quantity, cost) {
      const p = player.positions[side];
      p.shares = round(p.shares + quantity);
      p.cost = round(p.cost + cost);
    }

    sellShares(player, side, quantity, proceeds) {
      const p = player.positions[side];
      const basis = p.shares > EPS ? (p.cost * quantity) / p.shares : 0;
      p.shares = round(Math.max(0, p.shares - quantity));
      p.cost = round(Math.max(0, p.cost - basis));
      player.balance = round(player.balance + proceeds);
      player.realized = round(player.realized + proceeds - basis);
      return round(proceeds - basis);
    }

    recordTrade(side, action, quantity, price, actor, source, bot = false) {
      this.state.round.volume = round(
        this.state.round.volume + quantity * price,
      );
      this.state.trades.unshift({
        id: this.id("trade"),
        time: this.clock(),
        side,
        action,
        quantity,
        price,
        actor,
        source,
        bot,
      });
      this.state.trades = this.state.trades.slice(0, 60);
    }

    fill(order, offer, quantity) {
      const player = this.player(order.playerId);
      const total = round(quantity * offer.price);
      let profit;
      if (order.action === "buy") {
        this.creditShares(player, order.side, quantity, total);
        if (order.type === "limit")
          player.balance = round(
            player.balance + quantity * (order.price - offer.price),
          );
        else order.budget = round(order.budget - total);
      } else profit = this.sellShares(player, order.side, quantity, total);
      this.recordActivity(player, {
        type: order.action,
        side: order.side,
        shares: quantity,
        price: offer.price,
        total,
        profit,
      });

      if (offer.order) {
        const maker = offer.order;
        const other = this.player(maker.playerId);
        let makerProfit;
        if (maker.action === "sell")
          makerProfit = this.sellShares(other, order.side, quantity, total);
        else this.creditShares(other, order.side, quantity, total);
        this.recordActivity(other, {
          type: maker.action,
          side: order.side,
          shares: quantity,
          price: offer.price,
          total,
          profit: makerProfit,
        });
        maker.remaining = round(maker.remaining - quantity);
        maker.filled = round(maker.filled + quantity);
        maker.total = round(maker.total + total);
      } else {
        this.state.round.liquidityUsed[offer.id] = round(
          (this.state.round.liquidityUsed[offer.id] || 0) + quantity,
        );
        this.state.round.inventory ||= { up: 0, down: 0 };
        this.state.round.inventory[order.side] +=
          order.action === "buy" ? -quantity : quantity;
      }
      order.remaining = round(order.remaining - quantity);
      order.filled = round(order.filled + quantity);
      order.total = round(order.total + total);
      this.recordTrade(
        order.side,
        order.action,
        quantity,
        offer.price,
        player.name,
        offer.source,
        Boolean(player.bot),
      );
    }

    match(order, now = this.clock()) {
      for (const offer of this.offers(
        order.side,
        order.action,
        order.playerId,
        now,
      )) {
        if (order.remaining <= EPS) break;
        if (
          order.type === "limit" &&
          (order.action === "buy"
            ? offer.price > order.price + EPS
            : offer.price < order.price - EPS)
        )
          break;
        let quantity = Math.min(order.remaining, offer.quantity);
        if (order.action === "buy" && order.type === "market")
          quantity = Math.min(
            quantity,
            floorShares(order.budget / offer.price),
          );
        quantity = floorShares(quantity);
        if (quantity > EPS) this.fill(order, offer, quantity);
      }
      this.state.orders = this.state.orders.filter((o) => o.remaining > EPS);
    }

    place(id, request, internal = false) {
      if (!internal) this.advance();
      const player = this.player(id);
      if (request.roundId !== this.state.round.id)
        throw new Error(
          "A new round has started. Review the price and try again.",
        );
      const { side, action, type } = request;
      if (
        !["up", "down"].includes(side) ||
        !["buy", "sell"].includes(action) ||
        !["market", "limit"].includes(type)
      )
        throw new Error("Choose a valid order.");
      if (this.state.orders.filter((o) => o.playerId === id).length >= 50)
        throw new Error("Cancel an open order before placing another.");
      const quantity = floorShares(Number(request.quantity));
      const amount = round(Number(request.amount));
      const price = Number(request.price);
      if (
        type === "limit" &&
        (!Number.isFinite(price) ||
          price < 0.01 ||
          price > 0.99 ||
          Math.abs(price * 100 - Math.round(price * 100)) > EPS)
      )
        throw new Error("Limit price must be 1–99 cents.");
      if (
        (type === "limit" || action === "sell") &&
        (!Number.isFinite(quantity) || quantity < 0.0001 || quantity > 1000000)
      )
        throw new Error("Enter a valid number of shares.");
      if (
        type === "market" &&
        action === "buy" &&
        (!Number.isFinite(amount) || amount < 0.01 || amount > 1000000)
      )
        throw new Error("Enter at least 0.01 gold.");
      const reserve =
        action === "buy"
          ? type === "market"
            ? amount
            : round(quantity * price)
          : 0;
      if (reserve > player.balance + EPS)
        throw new Error("Not enough gold for this order.");
      if (action === "sell" && quantity > this.availableShares(id, side) + EPS)
        throw new Error(
          "Not enough available shares. Cancel any reserved sell orders first.",
        );
      const order = {
        id: this.id("order"),
        playerId: id,
        roundId: this.state.round.id,
        side,
        action,
        type,
        price,
        original: quantity,
        remaining: action === "buy" && type === "market" ? 1000000 : quantity,
        budget: amount,
        filled: 0,
        total: 0,
        created: this.clock(),
      };
      player.balance = round(player.balance - reserve);
      this.match(order);
      if (type === "market" && action === "buy")
        player.balance = round(player.balance + order.budget);
      if (type === "limit" && order.remaining > EPS)
        this.state.orders.push(order);
      return {
        id: order.id,
        filled: order.filled,
        total: order.total,
        remaining: type === "limit" ? order.remaining : 0,
        partial:
          type === "market" &&
          (action === "buy" ? order.budget > 0.01 : order.remaining > EPS),
      };
    }

    cancel(id, orderId, advance = true) {
      if (advance) this.advance();
      const index = this.state.orders.findIndex(
        (o) => o.id === orderId && o.playerId === id,
      );
      if (index < 0)
        throw new Error("This order has already filled or expired.");
      const [order] = this.state.orders.splice(index, 1);
      if (order.action === "buy")
        this.player(id).balance = round(
          this.player(id).balance + order.remaining * order.price,
        );
    }

    settle() {
      const r = this.state.round;
      const close = r.path[300];
      const outcome = close >= r.opening ? "up" : "down";
      for (const order of [...this.state.orders])
        this.cancel(order.playerId, order.id, false);
      const result = {
        id: r.id,
        start: r.start,
        end: r.end,
        opening: r.opening,
        close,
        outcome,
        volume: r.volume,
        path: r.path,
      };
      for (const player of Object.values(this.state.players)) {
        const cost = player.positions.up.cost + player.positions.down.cost;
        const payout = player.positions[outcome].shares;
        if (player.positions.up.shares + player.positions.down.shares > EPS) {
          player.balance = round(player.balance + payout);
          player.realized = round(player.realized + payout - cost);
          player.history.unshift({
            ...result,
            path: undefined,
            payout: round(payout),
            cost: round(cost),
            profit: round(payout - cost),
          });
          player.history = player.history.slice(0, 100);
          this.recordActivity(player, {
            type: "settlement",
            side: outcome,
            shares: player.positions[outcome].shares,
            total: round(payout),
            profit: round(payout - cost),
            time: r.end,
          });
        }
        player.positions = { up: emptyPosition(), down: emptyPosition() };
      }
      this.state.history.unshift(result);
      this.state.history = this.state.history.slice(0, 24);
      return close;
    }

    advance(now = this.clock()) {
      while (now >= this.state.round.end) {
        const nextStart = this.state.round.end;
        const close = this.settle();
        // After a long shutdown, settle the held round once and resume the current window.
        this.newRound(
          now - nextStart > ROUND_MS * 24
            ? Math.floor(now / ROUND_MS) * ROUND_MS
            : nextStart,
          close,
        );
      }
      const tick = Math.floor((now - this.state.round.start) / 1000);
      if (tick !== this.state.round.lastTick) {
        this.state.round.lastTick = tick;
        this.state.round.liquidityUsed = {};
        for (const order of [...this.state.orders].sort(
          (a, b) => a.created - b.created,
        )) {
          if (order.remaining > EPS) this.match(order, now);
        }
        if (
          this.botsEnabled &&
          tick % 3 === 0 &&
          tick !== this.state.round.botTick
        ) {
          this.state.round.botTick = tick;
          this.runBots(tick, now);
        }
      }
    }

    seedBots() {
      for (const strategy of ["Momentum", "Contrarian", "Noise"]) {
        const bot = this.addPlayer(`bot-${strategy.toLowerCase()}`);
        bot.name = strategy;
        bot.bot = true;
        bot.balance = 100000;
        bot.positions = {
          up: { shares: 2000, cost: 1000 },
          down: { shares: 2000, cost: 1000 },
        };
      }
    }

    runBots(tick, now) {
      // Every strategy sees only elapsed prices. Never use future points here.
      const rng = random(
        this.state.seed ^ (this.state.round.start + tick * 191),
      );
      const index = clamp(tick, 0, 300);
      const momentum =
        this.state.round.path[index] -
        this.state.round.path[Math.max(0, index - 12)];
      for (const strategy of ["Momentum", "Contrarian", "Noise"]) {
        const id = `bot-${strategy.toLowerCase()}`;
        if (!this.state.players[id]) continue;
        for (const order of [...this.state.orders].filter(
          (o) => o.playerId === id && now - o.created > 20000,
        ))
          this.cancel(id, order.id, false);
        if (rng() < 0.22) continue;
        let side = momentum >= 0 ? "up" : "down";
        if (strategy === "Contrarian") side = side === "up" ? "down" : "up";
        if (strategy === "Noise") side = rng() > 0.5 ? "up" : "down";
        const action = rng() > 0.35 ? "buy" : "sell";
        const quantity = Math.floor(8 + rng() * 55);
        const q = this.quotes(side, now);
        const type = rng() > 0.2 ? "market" : "limit";
        const price = action === "buy" ? q.bid : q.ask;
        try {
          this.place(
            id,
            {
              side,
              action,
              type,
              amount: round(quantity * q.ask),
              quantity,
              price,
              roundId: this.state.round.id,
            },
            true,
          );
        } catch {
          /* A bot with insufficient inventory waits for another opportunity. */
        }
      }
    }

    reset(id) {
      this.advance();
      for (const o of [...this.state.orders].filter((o) => o.playerId === id))
        this.cancel(id, o.id, false);
      const player = this.player(id);
      player.balance = 1000;
      player.positions = { up: emptyPosition(), down: emptyPosition() };
      player.history = [];
      player.realized = 0;
      player.activity = [];
      player.equityHistory = [];
      player.totalVolume = 0;
      player.biggestWin = 0;
      player.marketsTraded = 0;
      player.lastTradedRound = null;
      player.trackingSince = this.clock();
    }

    snapshot(id) {
      this.advance();
      const player = this.player(id);
      const r = this.state.round;
      const now = this.clock();
      const orders = this.state.orders
        .filter((o) => o.playerId === id)
        .map((o) => ({
          id: o.id,
          side: o.side,
          action: o.action,
          price: o.price,
          original: o.original,
          remaining: o.remaining,
          filled: o.filled,
        }));
      const positions = {};
      for (const side of ["up", "down"])
        positions[side] = {
          ...player.positions[side],
          available: this.availableShares(id, side),
          mark: this.quotes(side, now).bid,
        };
      const reserved = round(
        orders
          .filter((o) => o.action === "buy")
          .reduce((n, o) => n + o.price * o.remaining, 0),
      );
      const equity = round(
        player.balance +
          reserved +
          positions.up.shares * positions.up.mark +
          positions.down.shares * positions.down.mark,
      );
      player.trackingSince ||= now;
      player.equityHistory ||= [];
      const lastPoint = player.equityHistory.at(-1);
      if (!lastPoint || now - lastPoint.time >= 60000) {
        player.equityHistory.push({ time: now, value: round(equity - 1000) });
        if (player.equityHistory.length > 2000)
          player.equityHistory = player.equityHistory.filter(
            (_, i, points) => i >= points.length - 500 || i % 2 === 0,
          );
      }
      return {
        now,
        round: {
          id: r.id,
          start: r.start,
          end: r.end,
          opening: r.opening,
          price: this.price(now),
          volume: r.volume,
          points: r.path
            .slice(0, clamp(Math.floor((now - r.start) / 1000), 0, 300) + 1)
            .map((price, i) => ({ time: r.start + i * 1000, price })),
        },
        probability: this.probability(now),
        quotes: { up: this.quotes("up", now), down: this.quotes("down", now) },
        book: Object.fromEntries(
          ["up", "down"].map((side) => [
            side,
            {
              asks: this.offers(side, "buy", null, now).map(
                ({ price, quantity, source, id: orderId, order }) => ({
                  price,
                  quantity,
                  source,
                  id: orderId,
                  mine: order?.playerId === id,
                }),
              ),
              bids: this.offers(side, "sell", null, now).map(
                ({ price, quantity, source, id: orderId, order }) => ({
                  price,
                  quantity,
                  source,
                  id: orderId,
                  mine: order?.playerId === id,
                }),
              ),
            },
          ]),
        ),
        player: {
          name: player.name,
          bio: player.bio || "",
          avatar: player.avatar || 0,
          joinedAt: player.joinedAt || player.trackingSince,
          activity: player.activity || [],
          equityHistory: player.equityHistory,
          trackingSince: player.trackingSince,
          totalVolume: player.totalVolume || 0,
          biggestWin: player.biggestWin || 0,
          marketsTraded: player.marketsTraded || 0,
          equity,
          balance: player.balance,
          reserved: round(
            orders
              .filter((o) => o.action === "buy")
              .reduce((n, o) => n + o.price * o.remaining, 0),
          ),
          positions,
          orders,
          history: player.history,
          realized: player.realized,
        },
        trades: this.state.trades,
        history: this.state.history,
      };
    }
  }
  return { Market, ROUND_MS, floorShares };
})();
